    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
I=np.array(G['Demo pair 1 input']); O=np.array(G['Demo pair 1 output']); T=np.array(G['Test input'])
Q=[4,3,2,1,5,7,2,4,6]
def solve(I, ignore_vals={0,1}):
    res=[]
    for i in range(I.shape[0]):
        r=list(map(int,I[i]))
        cs=[(v,j) for j,v in enumerate(r) if v not in ignore_vals]
        cands=[s for s in range(9) if all(Q[(j-s)%9]==v for v,j in cs)]
        s=min(cands) if cands else None
        row=[Q[(j-s)%9] if s is not None and r[j]==0 else r[j] for j in range(I.shape[1])]
        res.append(row)
    return np.array(res,dtype=int)
for iv in [{}, {0},{0,1}]:
    F=solve(I,ignore_vals=iv)
    print('demo match:',np.all(F==O), 'ignore',iv)
Tres=solve(T,ignore_vals={0})
for r in Tres.tolist(): print(''.join(map(str,r)))
print(json.dumps(Tres.tolist()))

